def lexicalOrder(n: int) -> list[int]:
    res = []
    def dfs(curr):
        if curr > n: return
        res.append(curr)
        for d in range(10):
            if curr * 10 + d <= n:
                dfs(curr * 10 + d)
            else:
                break
    for start in range(1, 10):
        dfs(start)
    return res

